24	final class DeptracConfigReader
25	{
26	    /**
27	     * Reads one deptrac configuration file.
28	     *
29	     * @throws DocGenException when the file is missing or unparsable
30	     */
31	    public function read(string $path): LayerModel
32	    {
33	        if (!is_file($path)) {
34	            throw new DocGenException(sprintf('Deptrac config not found: %s', $path));
35	        }
36	
37	        try {
38	            $data = Yaml::parseFile($path);
39	        } catch (ParseException $exception) {
40	            throw new DocGenException('Invalid deptrac.yaml: ' . $exception->getMessage(), 0, $exception);
41	        }
42	
43	        if (!is_array($data)) {
44	            throw new DocGenException('Invalid deptrac.yaml: top-level value must be a mapping.');
45	        }
46	
47	        $section = isset($data['deptrac']) && is_array($data['deptrac']) ? $data['deptrac'] : $data;
48	
49	        return new LayerModel($this->layers($section), $this->ruleset($section));
50	    }
51	
52	    /**
53	     * Reads the layer definitions of a deptrac section.
54	     *
55	     * @param array<array-key, mixed> $section
56	     *
57	     * @return list<LayerDefinition>
58	     */
59	    public function layers(array $section): array
60	    {
61	        $layers = [];
62	        foreach (is_array($section['layers'] ?? null) ? $section['layers'] : [] as $layer) {
63	            if (!is_array($layer) || !is_string($layer['name'] ?? null)) {
64	                continue;
65	            }
66	
67	            $collectors = [];
68	            foreach (is_array($layer['collectors'] ?? null) ? $layer['collectors'] : [] as $collector) {
69	                if (is_array($collector) && is_string($collector['type'] ?? null) && is_string($collector['value'] ?? null)) {
70	                    $collectors[] = new LayerCollector($collector['type'], $collector['value']);
71	                }
72	            }
73	
74	            $layers[] = new LayerDefinition($layer['name'], $collectors);
75	        }
76	
77	        return $layers;
78	    }
79	
