33	    {
34	        if (!is_file($path)) {
35	            throw new DocGenException(sprintf('Composer manifest not found: %s', $path));
36	        }
37	
38	        $contents = file_get_contents($path);
39	        if ($contents === false) {
40	            throw new DocGenException(sprintf('Composer manifest is not readable: %s', $path));
41	        }
42	
43	        $data = json_decode($contents, true);
44	        if (!is_array($data)) {
45	            throw new DocGenException(sprintf('Invalid composer.json at %s: %s', $path, json_last_error_msg()));
46	        }
47	
48	        $directory = dirname($path);
49	        $name = isset($data['name']) && is_string($data['name']) && $data['name'] !== ''
50	            ? $data['name']
51	            : basename($directory);
52	
53	        return new ComposerManifest(
54	            $directory,
55	            $name,
56	            isset($data['description']) && is_string($data['description']) ? $data['description'] : '',
