112	    /**
113	     * Determines the state of one file between the compared revisions.
114	     *
115	     * @param ?string $code the file as the head revision has it
116	     * @param ?string $baseCode the file as the base revision had it
117	     */
118	    public function statusOf(RenderKit $services, ?string $code, ?string $baseCode): string
119	    {
