13	/**
14	 * Reads the installed package names of one composer.lock file.
15	 *
16	 * A lock file is the authoritative source for the runtime and dev split:
17	 * "packages" holds the runtime dependencies and "packages-dev" the ones
18	 * installed only for development.
19	 */
20	final class ComposerLockReader
21	{
22	    /**
23	     * Reads the runtime and dev package names of one composer.lock file.
24	     *
25	     * A missing, unreadable, or malformed lock file yields null instead of an
26	     * error, so documentation generation keeps working without it.
27	     *
28	     * @return array{runtime: list<string>, dev: list<string>}|null null when the file cannot be used
29	     */
30	    public function read(string $path): ?array
31	    {
32	        if (!is_file($path)) {
33	            return null;
34	        }
35	
36	        $contents = file_get_contents($path);
37	        if ($contents === false) {
38	            return null;
39	        }
40	
41	        $data = json_decode($contents, true);
42	        if (!is_array($data)) {
43	            return null;
44	        }
45	
46	        return [
47	            'runtime' => $this->names($data['packages'] ?? null),
48	            'dev' => $this->names($data['packages-dev'] ?? null),
49	        ];
50	    }
51	
52	    /**
53	     * Collects the package names of one composer.lock package section.
54	     *
55	     * @return list<string>
56	     */
57	    public function names(mixed $section): array
58	    {
59	        if (!is_array($section)) {
60	            return [];
61	        }
62	
63	        $names = [];
64	        foreach ($section as $entry) {
65	            $name = is_array($entry) ? ($entry['name'] ?? null) : null;
66	            if (is_string($name) && $name !== '') {
67	                $names[] = $name;
68	            }
69	        }
70	
71	        return $names;
72	    }
73	}
