40	     */
41	    public function __construct(
42	        ?ConfigScalarReader $scalarReader = null,
43	        ?ConfigStringListReader $stringListReader = null,
44	        ?BaseUrl $baseUrl = null,
45	    ) {
46	        $this->scalarReader = $scalarReader ?? new ConfigScalarReader();
47	        $this->stringListReader = $stringListReader ?? new ConfigStringListReader();
48	        $this->baseUrl = $baseUrl ?? new BaseUrl();
