51	    /**
52	     * Loads and validates a DocGen YAML configuration file.
53	     *
54	     * @throws DocGenException when the file is missing, unparsable, or contains invalid values
55	     */
56	    public function load(string $path): DocGenConfig
57	    {
58	        if (!is_file($path)) {
59	            throw new DocGenException(sprintf('DocGen config not found: %s', $path));
60	        }
61	
62	        try {
63	            $data = Yaml::parseFile($path);
64	        } catch (ParseException $exception) {
65	            throw new DocGenException('Invalid doc.yaml: ' . $exception->getMessage(), 0, $exception);
66	        }
67	
68	        if (!is_array($data)) {
69	            throw new DocGenException('Invalid doc.yaml: top-level value must be a mapping.');
70	        }
71	
72	        foreach (array_keys($data) as $key) {
73	            if (!in_array((string) $key, self::KNOWN_KEYS, true)) {
74	                throw new DocGenException(sprintf('Invalid doc.yaml: top-level contains unsupported key "%s".', $key));
75	            }
76	        }
