80	        return new DocGenConfig(
81	            $root === false ? dirname($path) : $root,
82	            $this->stringListReader->read($data, 'packages', ['.', 'packages/*']),
83	            $this->stringListReader->read($data, 'vendor', []),
84	            $this->stringListReader->read($data, 'exclude', []),
85	            $this->scalarReader->string($data, 'output', 'build/docs'),
86	            $this->scalarReader->optionalString($data, 'title'),
87	            $this->scalarReader->optionalString($data, 'deptrac'),
88	            $this->scalarReader->optionalString($data, 'coverage'),
89	            $this->stringListReader->read($data, 'vendor_dev', []),
90	            $this->scalarReader->optionalPath($data, 'cache', DocGenConfig::DEFAULT_CACHE),
91	            $this->baseUrl->normalize($this->scalarReader->optionalString($data, 'base_url')),
