22	final class BaseUrl
23	{
24	    /**
25	     * Returns one configured address without its trailing slash.
26	     *
27	     * An empty value is the same answer as no value at all: nothing about
28	     * the site changes, rather than an address that resolves nowhere.
29	     *
30	     * @throws DocGenException when the value is not an absolute http address
31	     */
32	    public function normalize(?string $value): ?string
33	    {
34	        if ($value === null) {
35	            return null;
36	        }
37	
38	        $trimmed = trim($value);
39	        if ($trimmed === '') {
40	            return null;
41	        }
42	
43	        if (preg_match('#^https?://[^\s/?\#]+(/[^\s?\#]*)?$#', $trimmed) !== 1) {
44	            throw new DocGenException(sprintf(
45	                'Invalid base_url: %s. Use the absolute address the site is published at, such as https://example.github.io/project.',
46	                $trimmed,
47	            ));
48	        }
49	
50	        return rtrim($trimmed, '/');
51	    }
